package com.vr3th.mediacompressor.engine
import android.content.Context;import android.graphics.Bitmap;import android.media.MediaMetadataRetriever;import android.net.Uri
import com.vr3th.mediacompressor.data.ProcessResult;import com.vr3th.mediacompressor.utils.StorageUtils;import java.io.File;import java.io.FileOutputStream
class GifEngine(private val context:Context){
 fun extractFramesAsGif(videoUri:Uri,originalName:String,fps:Int=10,maxDurationMs:Long=6000):ProcessResult{val s=System.currentTimeMillis();var orig=0L;context.contentResolver.openFileDescriptor(videoUri,"r")?.use{orig=it.statSize};val r=MediaMetadataRetriever();val out=StorageUtils.createTempFile(context,"anim_",".gif");try{r.setDataSource(context,videoUri);val dur=(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull()?:1000L).coerceAtMost(maxDurationMs);val interval=1000L/fps;val count=(dur/interval).toInt().coerceAtMost(60);val frames=mutableListOf<Bitmap>();for(i in 0 until count){r.getFrameAtTime(i*interval*1000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC)?.let{f->val sc=Bitmap.createScaledBitmap(f,360,(360*f.height)/f.width,true);frames.add(sc);if(sc!==f)f.recycle()}};if(frames.isEmpty())throw IllegalStateException("Unable to extract video frames for GIF.");writeAnimatedGif(out,frames,(100/fps).coerceAtLeast(5));frames.forEach{it.recycle()};return ProcessResult(true,originalName,orig,out.length(),"Video","360p",30,fps,"Video","GIF",System.currentTimeMillis()-s,out.absolutePath)}catch(x:Exception){return ProcessResult(false,originalName,orig,0,"-","-",0,0,"-","-",0,"",errorMessage=x.localizedMessage?:"GIF generation failed")}finally{try{r.release()}catch(_:Exception){}}}
 private fun writeAnimatedGif(out:File,frames:List<Bitmap>,delay:Int){FileOutputStream(out).use{o->o.write("GIF89a".toByteArray());val w=frames[0].width;val h=frames[0].height;o.write(byteArrayOf((w and 255).toByte(),(w shr 8).toByte(),(h and 255).toByte(),(h shr 8).toByte(),0xF7.toByte(),0,0));for(r in 0..5)for(g in 0..5)for(b in 0..5)o.write(byteArrayOf((r*51).toByte(),(g*51).toByte(),(b*51).toByte()));repeat(40){o.write(byteArrayOf(0,0,0))};o.write(byteArrayOf(0x21,0xFF.toByte(),0x0B,0x4E,0x45,0x54,0x53,0x43,0x41,0x50,0x45,0x32,0x2E,0x30,0x03,0x01,0,0,0));for(bmp in frames){o.write(byteArrayOf(0x21,0xF9.toByte(),4,0,(delay and 255).toByte(),(delay shr 8).toByte(),0,0));o.write(byteArrayOf(0x2C,0,0,0,0,(w and 255).toByte(),(w shr 8).toByte(),(h and 255).toByte(),(h shr 8).toByte(),0));o.write(8);val n=w*h;val idx=ByteArray(n);val px=IntArray(n);bmp.getPixels(px,0,w,0,0,w,h);for(i in 0 until n){val c=px[i];val rr=((c shr 16)and 255)/51;val gg=((c shr 8)and 255)/51;val bb=(c and 255)/51;idx[i]=(rr*36+gg*6+bb).toByte()};var p=0;while(p<n){val z=minOf(254,n-p);o.write(z+1);o.write(0x80);o.write(idx,p,z);p+=z};o.write(1);o.write(0x81);o.write(0)};o.write(0x3B)}}
}
